#if UNITY_EDITOR
using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine;
namespace LastRail.Tests.EditMode {
 public class BMiraEquippedLiveTests {
  BMiraEquippedNativeFixture fixture;BDirectAttackBasicLoop root;BDirectAttackBasicLoopBinding binding;BMiraEquippedTrialContext context;BBoardingEventsNodeSnapshot node;BWaveBoardingLocalPaths paths;MiraJudgementSceneAdapter scene;BTravelRuntimeConfiguration motion;long index;
  static object Invoke(Type t,object o,string name,params object[] args){var m=t.GetMethod(name);Assert.That(m,Is.Not.Null,name+" equipped native connection missing");try{return m.Invoke(o,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  void Create(string trial,int shieldTarget=-1,bool blocker=false){fixture=new BMiraEquippedNativeFixture(trial);context=fixture.Source();node=fixture.Node();binding=fixture.Binding(shieldTarget<0?null:new JArray(new JObject{["targetId"]=node.OriginalSource.Waves[0].Instances[shieldTarget].InstanceId,["sourceEntity"]="LOCAL_ORIGINAL",["sourceAbility"]="LOCAL_SECONDARY_SHIELD_FIXTURE",["effectIndex"]=0,["amount"]=10,["expiryTick"]=1000}));paths=fixture.Paths(binding.Composition.Attack);scene=fixture.Scene();if(blocker)scene.AddApprovedTestBox("EQUIPPED_BOX",15000,3000);var rail=global::CombatRailJourneyTests.Config();rail["offers"]=new JArray();rail["throttleMaximumBps"]=13000;rail["throttleCruiseBps"]=10000;motion=BTravelRuntimeConfiguration.LocalValidation(rail,BDirectAttackInput.Digest(rail));root=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),null,"CreateMiraEquippedTrialRuntime",binding,node,paths,context,scene,10000,motion);}
  JObject State(BDirectAttackBasicLoop r=null)=>(JObject)(r??root).Capture()["miraFirstTrial"];
  JArray Shots(BDirectAttackBasicLoop r=null)=>(JArray)State(r)["shots"];
  void Frame(BDirectAttackBasicLoop r=null,string id=null)=>(r??root).AdvanceMiraFirstFrame(id??"eq-frame-"+(++index),binding.Composition.Attack.StepTimeSpanTicks,scene);
  void Fire(){for(int i=0;i<220&&Shots().Count==0;i++)Frame();Assert.That(Shots().Count,Is.GreaterThan(0));}
  void Finish(){for(int i=0;i<70&&Shots().Any(s=>(string)s["status"]=="FLYING");i++)Frame();}
  BDirectAttackBasicLoop Restore(JObject p)=>(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),null,"RestoreMiraEquippedTrialRuntime",p,BDirectAttackInput.Digest(p),binding,node,paths,context,scene,10000,motion);
  void Observe(string operation,JObject values){var p=(JObject)values.DeepClone();p["kind"]="LOCAL_ORIGINAL";p["eventId"]="eq-original-"+(++index);p["operation"]=operation;root.ObserveMiraFirstOriginal((string)p["eventId"],p);}
  void Layout(int extra,int distance=1000){var rows=(JArray)scene.Observe(0,1)["targets"];var main=rows.Single(x=>(string)x["id"]==fixture.TargetId);var mainAnchor=new Vector3((long)main["anchorMm"][0]/1000f,(long)main["anchorMm"][1]/1000f,(long)main["anchorMm"][2]/1000f);int ordinal=0;foreach(var row in rows){string id=(string)row["id"];if(id==fixture.TargetId)continue;var t=scene.GetComponentsInChildren<Transform>().Single(v=>v.name==id);ordinal++;if(ordinal<=extra){float h=((long)row["anchorMm"][1]-(long)row["feetMm"][1])/1000f;t.position=mainAnchor+Vector3.right*(distance*ordinal/1000f)-Vector3.up*h;}else t.position+=Vector3.forward*100;}}
  static JObject Trust(JObject p)=>new JObject(new[]{"origin","nativeContextId","seedHash","sourceHash","nodeId","visitDepth","priorSourceHash"}.Select(k=>new JProperty(k,p[k].DeepClone())));
  [TestCase(0,1)][TestCase(1,2)][TestCase(2,3)][TestCase(3,3)]public void ActualExtraEnemyCountProducesAtMostTwoSecondaryBranches(int extra,int expected){Create("highest");Layout(extra);Fire();Assert.That(Shots().Count,Is.EqualTo(expected));Assert.That(Shots().Select(x=>(string)x["targetId"]).Distinct().Count(),Is.EqualTo(expected));}
  [TestCase(6000,2)][TestCase(6001,1)]public void SecondaryRadiusUsesInclusiveSixMetreIntersection(int distance,int expected){Create("highest");Layout(1,distance);Fire();Assert.That(Shots().Count,Is.EqualTo(expected));}
  [TestCase("one",10)][TestCase("two",17)]public void SecondaryCoefficientIsAppliedBeforeOneFinalFloor(string trial,int expected){Create(trial);Layout(1);Fire();var s=Shots().Single(x=>(string)x["kind"]=="SECONDARY");int before=root.Hp((string)s["targetId"]);Finish();Assert.That(root.Hp((string)s["targetId"]),Is.EqualTo(before-expected));}
  [Test]public void SecondaryUsesOriginalTargetShieldAndHpExactlyOnce(){Create("highest",1);Layout(1);Fire();var s=Shots().Single(x=>(string)x["kind"]=="SECONDARY");int before=root.Hp((string)s["targetId"]);Finish();var receipt=((JArray)State()["contacts"]).Single(x=>(string)x["eventId"]==(string)s["id"]+":hp");Assert.That((int)receipt["hp"]["absorbed"],Is.EqualTo(10));Assert.That(root.Hp((string)s["targetId"]),Is.EqualTo(before-7));var saved=root.Capture();string id=(string)((JArray)saved["commands"]).Last["eventId"];Frame(root,id);Assert.That(JToken.DeepEquals(saved,root.Capture()),Is.True);}
  [Test]public void PrimaryDeathDoesNotCancelSurvivingSecondary(){Create("highest");Layout(2);Fire();Observe("DAMAGE",new JObject{["targetId"]=fixture.TargetId,["amount"]=root.Hp(fixture.TargetId)});Finish();Assert.That((string)Shots()[0]["status"],Is.EqualTo("MISS"));Assert.That(Shots().Skip(1).All(x=>(string)x["status"]=="HIT"),Is.True);Assert.That(((JArray)State()["contacts"]).Count,Is.EqualTo(2));}
  [Test]public void SecondaryLethalContactHasOneNativeDeathAndReplay(){Create("highest");Layout(1);Fire();string target=(string)Shots()[1]["targetId"];Observe("DAMAGE",new JObject{["targetId"]=target,["amount"]=root.Hp(target)-5});Finish();Assert.That(root.Hp(target),Is.Zero);var saved=JObject.Parse(root.Capture().ToString());Assert.That(((JArray)saved["boarding"]["events"]).Count(x=>(string)x["kind"]=="UNREGISTER_DEATH"&&(string)x["instanceId"]==target),Is.EqualTo(1));Assert.That(JToken.DeepEquals(saved,Restore(saved).Capture()),Is.True);}
  [Test]public void EquippedNodeCheckpointPublishesNativePosesAfterWholeVerification(){Create("highest");Fire();var original=node.OriginalSource.Capture();using(var controller=new BNodeSessionController(context.AccountId,context.RunId)){controller.BindVerifiedNode(original,Trust(original),0);controller.AttachLocalTravel(node,motion,(n,m)=>root,controller.Revision);var saved=JObject.Parse(controller.Capture().ToString());var t=typeof(BNodeSessionController).Assembly.GetType("LastRail.Run.BMiraFirstNodeCheckpoint");using(var restored=(BNodeSessionController)Invoke(t,null,"RestoreEquipped",saved,BDirectAttackInput.Digest(saved),Trust(original),binding,node,paths,context,scene,10000,motion)){Assert.That(JToken.DeepEquals(saved,restored.Capture()),Is.True);}}}
  [Test]public void ActualSecondaryFeedbackUsesDistinctBranchKindsAndNoHistoricalPulseOnRestore(){Create("highest");Layout(2);Fire();var feedback=new MiraFirstFeedbackController();JObject frame=null;feedback.Bind(x=>frame=x,()=>{},root.Capture());Assert.That(((JArray)frame["flights"]).Count(x=>(string)x["kind"]=="SECONDARY"),Is.EqualTo(2));Assert.That(((JArray)frame["pulses"]).Count,Is.Zero);Finish();feedback.Observe(root.Capture());Assert.That(((JArray)frame["pulses"]).Count(x=>(string)x["kind"]=="HP"),Is.EqualTo(3));feedback.Unbind();var frozen=(JObject)frame.DeepClone();feedback.Observe(root.Capture());Assert.That(JToken.DeepEquals(frozen,frame),Is.True);}
  [Test]public void ArrivalDefenseAndShieldUseEachTargetWhileLaunchAttackStaysFrozen(){Create("highest");Layout(1);Fire();int mainHp=root.Hp(fixture.TargetId);string secondary=(string)Shots()[1]["targetId"];int secondaryHp=root.Hp(secondary);Observe("ATTACK",new JObject{["value"]=new JObject{["numerator"]="1",["denominator"]="1"}});Observe("DEFENSE",new JObject{["value"]=new JObject{["numerator"]="1000",["denominator"]="1"}});Observe("SHIELD",new JObject{["amount"]=10,["expiry"]=1000});Finish();Assert.That(root.Hp(fixture.TargetId),Is.EqualTo(mainHp-27));Assert.That(root.Hp(secondary),Is.EqualTo(secondaryHp-17));}
  [Test]public void DeadSecondaryGenerationMissesWithoutRetargeting(){Create("highest");Layout(2);Fire();string target=(string)Shots()[1]["targetId"];Observe("DAMAGE",new JObject{["targetId"]=target,["amount"]=root.Hp(target)});Finish();Assert.That((string)Shots()[1]["status"],Is.EqualTo("MISS"));Assert.That((string)Shots()[2]["status"],Is.EqualTo("HIT"));Assert.That(((JArray)State()["contacts"]).Count,Is.EqualTo(2));}
  [Test]public void HoldAndDuplicateFrameDoNotAdvanceOrDuplicateSecondary(){Create("highest");Layout(2);Fire();root.SetPaused("eq-pause",true);long tick=root.Tick;Frame();Assert.That(root.Tick,Is.EqualTo(tick));Assert.That(Shots().All(x=>(string)x["status"]=="FLYING"),Is.True);var saved=JObject.Parse(root.Capture().ToString());Assert.That(JToken.DeepEquals(saved,Restore(saved).Capture()),Is.True);root.SetPaused("eq-resume",false);Finish();Assert.That(((JArray)State()["contacts"]).Count,Is.EqualTo(3));}
  [Test]public void SecondaryWithinRadiusStillNeedsOriginalRange(){Create("highest");Layout(1);var rows=(JArray)scene.Observe(0,1)["targets"];var muzzle=scene.GetComponentsInChildren<Transform>().Single(t=>t.name=="JudgementMuzzle_NotArtSocket");var main=rows.Single(t=>(string)t["id"]==fixture.TargetId);var secondary=rows.First(t=>(string)t["id"]!=fixture.TargetId);foreach(var pair in new[]{(main,23f),(secondary,28f)}){var t=scene.GetComponentsInChildren<Transform>().Single(v=>v.name==(string)pair.Item1["id"]);float h=((long)pair.Item1["anchorMm"][1]-(long)pair.Item1["feetMm"][1])/1000f;t.position=muzzle.position+Vector3.forward*pair.Item2-Vector3.up*h;}Fire();Assert.That(Shots().Count,Is.EqualTo(1));}
  [Test]public void SecondaryInsideRadiusButBehindOriginalSolidIsExcluded(){Create("highest",-1,true);Layout(1,4000);scene.GetComponentsInChildren<Transform>().Single(t=>t.name=="EQUIPPED_BOX").position=new Vector3(15,.8f,3);Fire();Assert.That(Shots().Count,Is.EqualTo(1));}
  [Test]public void OriginalNodeCallbackDrivesRealSecondaryViewWithoutOwningHp(){Create("highest");Layout(2);Fire();var p=node.OriginalSource.Capture();using(var controller=new BNodeSessionController(context.AccountId,context.RunId)){controller.BindVerifiedNode(p,Trust(p),0);controller.AttachLocalTravel(node,motion,(n,m)=>root,controller.Revision);var viewObject=new GameObject("ActualEquippedFeedbackView");viewObject.transform.SetParent(scene.transform,false);var view=viewObject.AddComponent<MiraFirstFeedbackView>();view.BindBasis(scene.transform);var feedback=new MiraFirstFeedbackController();JObject frame=null;try{feedback.Bind(x=>{frame=x;view.ApplyFrame(x);},view.Clear,controller.Capture());controller.Bind(feedback.Observe);Assert.That(((JArray)frame["flights"]).Count(x=>(string)x["kind"]=="SECONDARY"),Is.EqualTo(2));var before=root.Capture();view.SetVisible(false);view.SetVisible(true);Assert.That(JToken.DeepEquals(before,root.Capture()),Is.True);for(int i=0;i<60;i++)controller.AdvanceMiraFirstFrame("node-view-"+i,binding.Composition.Attack.StepTimeSpanTicks,scene,controller.Revision);Assert.That(((JArray)State()["contacts"]).Count,Is.EqualTo(3));feedback.Unbind();controller.Unbind();Assert.That(viewObject.transform.childCount,Is.Zero);}finally{feedback.Unbind();UnityEngine.Object.DestroyImmediate(viewObject);}}}
  [TearDown]public void Cleanup(){if(scene!=null)UnityEngine.Object.DestroyImmediate(scene.gameObject);}
  [TestCase("none",0)][TestCase("one",1500)][TestCase("two",2500)][TestCase("highest",2500)]
  public void ActualSavedEquippedSourceBindsOriginalNativeFireAndFrozenContext(string trial,int coefficient){Create(trial);Fire();Assert.That(JToken.DeepEquals(State()["context"],context.Capture()),Is.True);Assert.That((string)Shots()[0]["attack"]["completedAttack"]["numerator"],Is.EqualTo("7472619"));Assert.That((string)Shots()[0]["attack"]["completedAttack"]["denominator"],Is.EqualTo("100000"));Assert.That((long)root.Capture()["state"]["direct"]["next"]["op_mira"],Is.EqualTo(root.Tick+180));Assert.That(Shots().Count,Is.LessThanOrEqualTo(3));if(coefficient==0)Assert.That(Shots().Count,Is.EqualTo(1));else Assert.That(Shots().Skip(1).All(s=>(int)s["coefficientBps"]==coefficient),Is.True);}
  [Test]public void FullInFlightJsonReplayPreservesBranchesAndHpOnce(){Create("highest");Fire();var saved=JObject.Parse(root.Capture().ToString());var restored=Restore(saved);Assert.That(JToken.DeepEquals(saved,restored.Capture()),Is.True);for(int i=0;i<55;i++){string id="continue-"+i;Frame(root,id);Frame(restored,id);}Assert.That(JToken.DeepEquals(root.Capture(),restored.Capture()),Is.True);var after=JObject.Parse(root.Capture().ToString());Assert.That(JToken.DeepEquals(after,Restore(after).Capture()),Is.True);}
  [Test]public void ActualSecondaryBranchesReachIndependentNativeHp(){Create("highest");Fire();Assert.That(Shots().Count,Is.EqualTo(3),"Must fire actual secondary branches");var initial=Shots().ToDictionary(s=>(string)s["targetId"],s=>root.Hp((string)s["targetId"]));Finish();Assert.That(Shots().All(s=>(string)s["status"]=="HIT"),Is.True);foreach(var s in Shots()){int expected=(string)s["kind"]=="SECONDARY"?17:70;Assert.That(root.Hp((string)s["targetId"]),Is.EqualTo(initial[(string)s["targetId"]]-expected));}Assert.That(((JArray)State()["contacts"]).Count,Is.EqualTo(3));}
 }
}
